package com.orderflow.product;
import jakarta.persistence.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.cache.annotation.CacheEvict;import org.springframework.cache.annotation.EnableCaching;import org.springframework.context.annotation.Configuration;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.io.Serializable;import java.math.BigDecimal;import java.time.Instant;import java.util.*;
@SpringBootApplication @EnableCaching public class ProductApplication{public static void main(String[]a){SpringApplication.run(ProductApplication.class,a);}}
@Entity @Table(name="categories",schema="product")class Category{@Id UUID id;@Column(unique=true)String name;protected Category(){}}
@Entity @Table(name="products",schema="product")class Product{@Id UUID id;@Column(unique=true)String sku;String name;String description;BigDecimal price;@Column(name="category_id")UUID categoryId;boolean active;@Column(name="updated_at")Instant updatedAt;protected Product(){}Product(ProductRequest r){id=UUID.randomUUID();apply(r);}void apply(ProductRequest r){sku=r.sku();name=r.name();description=r.description();price=r.price();categoryId=r.categoryId();active=r.active();updatedAt=Instant.now();}}
interface ProductRepo extends JpaRepository<Product,UUID>,JpaSpecificationExecutor<Product>{}
record ProductRequest(@NotBlank String sku,@NotBlank String name,@NotNull String description,@NotNull@DecimalMin("0.0")BigDecimal price,@NotNull UUID categoryId,boolean active){}
record ProductView(UUID id,String sku,String name,String description,BigDecimal price,UUID categoryId,boolean active,Instant updatedAt)implements Serializable{static ProductView of(Product p){return new ProductView(p.id,p.sku,p.name,p.description,p.price,p.categoryId,p.active,p.updatedAt);}}
@Service class ProductService{private final ProductRepo repo;ProductService(ProductRepo r){repo=r;}@org.springframework.cache.annotation.Cacheable(value="products",key="#id")ProductView get(UUID id){return repo.findById(id).map(ProductView::of).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}@Transactional @CacheEvict(value="products",allEntries=true)ProductView create(ProductRequest r){return ProductView.of(repo.save(new Product(r)));}@Transactional @CacheEvict(value="products",key="#id")ProductView update(UUID id,ProductRequest r){Product p=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));p.apply(r);return ProductView.of(p);}@Transactional @CacheEvict(value="products",key="#id")void delete(UUID id){if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);repo.deleteById(id);}Page<ProductView> search(String q,UUID category,Pageable page){return repo.findAll((root,cq,cb)->{var p=cb.conjunction();if(q!=null&&!q.isBlank())p=cb.and(p,cb.like(cb.lower(root.get("name")),"%"+q.toLowerCase()+"%"));if(category!=null)p=cb.and(p,cb.equal(root.get("categoryId"),category));return cb.and(p,cb.isTrue(root.get("active")));},page).map(ProductView::of);}}
@RestController @RequestMapping("/api/products")class ProductController{private final ProductService service;ProductController(ProductService s){service=s;}@GetMapping Page<ProductView>list(@RequestParam(required=false)String q,@RequestParam(required=false)UUID category,@PageableDefault(size=20,sort="name")Pageable page){return service.search(q,category,page);}@GetMapping("/{id}")ProductView get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED)ProductView create(@Valid@RequestBody ProductRequest r){return service.create(r);}@PutMapping("/{id}")ProductView update(@PathVariable UUID id,@Valid@RequestBody ProductRequest r){return service.update(id,r);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID id){service.delete(id);}}
